            secondary.OWNINGBUSINESSUNITNAME as SECONDARY_OWNINGBUSINESSUNITNAME
    from wo_data
    left join MSDYN_CUSTOMERASSET_REF machine on
        wo_data.WO_PRODUCTSN = machine.ID
    left join MSDYN_PROJECT_REF wogroupno on
        wo_data.WO_WOPJCODE = wogroupno.ID
    left join MSDYN_WORKORDERSUBSTATUS_REF wostatus on
        wo_data.MSDYN_SUBSTATUS = wostatus.ID
    left join TEAM_REF team on
        wo_data.WO_TEAMINCHARGE = team.ID
    left join TEL_COM_SALESORDERHEADER_REF primary on
        wo_data.TEL_WO_PRIMARY_SO = primary.ID
    left join TEL_COM_SALESORDERHEADER_REF secondary on
        wo_data.TEL_WO_SECONDARY_SO = secondary.ID
),

